use ignite_eval::Json;
use std::{fmt::Write as _,hint::black_box,time::Instant};
fn old(out:&mut String,text:&str){out.push('"');for c in text.chars(){match c{'"'=>out.push_str("\\\""),'\\'=>out.push_str("\\\\"),'\n'=>out.push_str("\\n"),'\t'=>out.push_str("\\t"),'\r'=>out.push_str("\\r"),'\u{8}'=>out.push_str("\\b"),'\u{c}'=>out.push_str("\\f"),c if(c as u32)<0x20=>out.push_str(&format!("\\u{:04x}",c as u32)),c=>out.push(c)}}out.push('"');}
fn spans(out:&mut String,text:&str){out.push('"');let mut start=0;for(i,b)in text.bytes().enumerate(){if b<0x20||b==b'"'||b==b'\\'{out.push_str(&text[start..i]);match b{b'"'=>out.push_str("\\\""),b'\\'=>out.push_str("\\\\"),b'\n'=>out.push_str("\\n"),b'\t'=>out.push_str("\\t"),b'\r'=>out.push_str("\\r"),8=>out.push_str("\\b"),12=>out.push_str("\\f"),_=>{write!(out,"\\u{b:04x}").unwrap();}}start=i+1;}}out.push_str(&text[start..]);out.push('"');}
fn gather<'a>(v:&'a Json,out:&mut Vec<&'a str>){match v{Json::Str(s)=>out.push(s),Json::Array(a)=>for x in a{gather(x,out)},Json::Object(o)=>for(k,x)in o{out.push(k);gather(x,out)},_=>{}}}
fn run(f:fn(&mut String,&str),ss:&[&str])->f64{let mut out=String::new();let t=Instant::now();for _ in 0..1000{out.clear();for s in ss{f(&mut out,black_box(s));}black_box(&out);}t.elapsed().as_secs_f64()}
fn old_pad(out:&mut String,indent:usize){for _ in 0..indent{out.push_str("  ");}}
fn chunk_pad(out:&mut String,indent:usize){const S:&str="                                ";for _ in 0..indent/(S.len()/2){out.push_str(S);}out.push_str(&S[..(indent%(S.len()/2))*2]);}
fn depths(v:&Json,d:usize,out:&mut Vec<usize>){match v{Json::Object(o)if !o.is_empty()=>{for x in o.values(){out.push(d+1);depths(x,d+1,out)}out.push(d)},Json::Array(a)if !a.is_empty()=>{for x in a{out.push(d+1);depths(x,d+1,out)}out.push(d)},_=>{}}}
fn run_pad(f:fn(&mut String,usize),ds:&[usize])->f64{let mut out=String::new();let t=Instant::now();for _ in 0..1000{out.clear();for d in ds{f(&mut out,black_box(*d));}black_box(&out);}t.elapsed().as_secs_f64()}
fn main(){let text=std::fs::read_to_string(std::env::args().nth(1).unwrap()).unwrap();let model=Json::parse(&text).unwrap();let mut ss=Vec::new();gather(&model,&mut ss);let controls:String=(0..32).map(|n|char::from_u32(n).unwrap()).collect();let extras=[controls,"plain\\\" 😀é中\u{7f}\n\r\t".into(),"".into()];for s in ss.iter().copied().chain(extras.iter().map(String::as_str)){let(mut a,mut b)=(String::new(),String::new());old(&mut a,s);spans(&mut b,s);assert_eq!(a,b);assert_eq!(Json::parse(&a).unwrap(),Json::Str(s.to_string()));}println!("strings={} bytes={}",ss.len(),ss.iter().map(|s|s.len()).sum::<usize>());let mut ds=Vec::new();depths(&model,0,&mut ds);for d in (0..96).chain(ds.iter().copied()){let(mut a,mut b)=(String::new(),String::new());old_pad(&mut a,d);chunk_pad(&mut b,d);assert_eq!(a,b);}println!("pads={}",ds.len());for i in 0..5{let(a,b)=if i%2==0{(run_pad(old_pad,&ds),run_pad(chunk_pad,&ds))}else{let b=run_pad(chunk_pad,&ds);(run_pad(old_pad,&ds),b)};println!("pad_pair={i} old={a:.9} chunk={b:.9}");}for i in 0..5{let(a,b)=if i%2==0{(run(old,&ss),run(spans,&ss))}else{let b=run(spans,&ss);(run(old,&ss),b)};println!("pair={i} old={a:.9} spans={b:.9}");}}
